export default function CrascMap({ onRegionPress }) {
  const [hoveredRegion, setHoveredRegion] = useState(null);

  const handlePress = (region) => {
    if (onRegionPress) {
      onRegionPress(region);
    } else {
        Alert.alert(region.name, "Navigation not implemented yet");
    }
  };

  return (
    <View style={{ aspectRatio: 535/555, width: '100%' }}>
      <Svg
        viewBox="0 0 535 555"
        width="100%"
        height="100%"
      >
        {regions.map((region) => (
          <G key={region.id} onPress={() => handlePress(region)}>
             <Path
                d={region.path}
                fill={hoveredRegion === region.id ? region.hoverColor : region.color}
                stroke="#2c3e50"
                strokeWidth="1"
                strokeLinejoin="round"
             />
          </G>
        ))}
      </Svg>
    </View>
  );
}